package com.example.todo.repository; import com.example.todo.entity.*; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.JpaRepository; public interface TodoRepository extends JpaRepository<Todo,Long>{Page<Todo> findByUser(User u,Pageable p); Page<Todo> findByUserAndTitleContainingIgnoreCase(User u,String s,Pageable p); Page<Todo> findByUserAndCompleted(User u,boolean c,Pageable p); Page<Todo> findByUserAndCompletedAndTitleContainingIgnoreCase(User u,boolean c,String s,Pageable p);}
